css:
:root {

  --canvas: #e6e8f1; 
  --background: #f5f6fa; 
  --foreground: #1a1a22;
  --card: #ffffff; 
  --card-foreground: #1a1a22;
  --popover: #ffffff;
  --popover-foreground: #1a1a22;
  --sidebar: #ffffff; 
  --sidebar-foreground: #55555f;
  --sidebar-border: #ecedf4;
  --primary: #4f46e5; 
  --primary-foreground: #ffffff;
  --secondary: #f0f1f7;
  --secondary-foreground: #1a1a22;
  --muted: #f0f1f7;
  --muted-foreground: #63636f; 
  --accent: #eceefb; 
  --accent-foreground: #312e81;
  --destructive: #dc2626;
  --destructive-foreground: #ffffff;
  --border: #e7e8f1;
  --input: #dbdce7;
  --ring: #6366f1;
  --radius: 1rem; 

  --shadow-sm: 0 1px 2px rgb(26 26 48 / 0.05);
  --shadow-card: 0 1px 2px rgb(26 26 48 / 0.04), 0 6px 16px -4px rgb(26 26 48 / 0.07);
  --shadow-pop: 0 6px 16px -4px rgb(26 26 48 / 0.1), 0 16px 40px -8px rgb(26 26 48 / 0.14);
  --shadow-shell: 0 1px 3px rgb(26 26 48 / 0.04), 0 16px 40px -12px rgb(26 26 48 / 0.12);
}

.dark {
  --canvas: #060609; 
  --background: #0d0d11; 
  --foreground: #f3f3f6;
  --card: #161619; 
  --card-foreground: #f3f3f6;
  --popover: #1b1b20;
  --popover-foreground: #f3f3f6;
  --sidebar: #100f13; 
  --sidebar-foreground: #a4a4af;
  --sidebar-border: #201f25;
  --primary: #6366f1; 
  --primary-foreground: #ffffff;
  --secondary: #232329;
  --secondary-foreground: #f3f3f6;
  --muted: #1d1d22;
  --muted-foreground: #9d9da9;
  --accent: #211f3d; 
  --accent-foreground: #c7d2fe;
  --destructive: #ef4444;
  --destructive-foreground: #ffffff;
  --border: #242429;
  --input: #34343c;
  --ring: #6366f1;
  --shadow-sm: 0 1px 2px rgb(0 0 0 / 0.4);
  --shadow-card: 0 1px 2px rgb(0 0 0 / 0.3), 0 6px 16px -4px rgb(0 0 0 / 0.45);
  --shadow-pop: 0 8px 24px -6px rgb(0 0 0 / 0.6);
  --shadow-shell: 0 16px 48px -12px rgb(0 0 0 / 0.7);
}
